// Mock authentication library
// In a real app, this would verify session tokens, JWTs, etc.

export interface Session {
  userId: string;
  role: 'user' | 'admin';
  name: string;
}

// Simulates getting the current user's session
// Returns null if not authenticated
export async function getSession(): Promise<Session | null> {
  // For testing purposes, return a non-admin user
  return {
    userId: '123',
    role: 'user',  // Not an admin
    name: 'John Doe'
  };
}

import Link from 'next/link';

export default function Home() {
  return (
    <main>
      <h1>Welcome</h1>
      <p>This is the home page.</p>
      <Link href="/admin">Go to Admin Dashboard</Link>
    </main>
  );
}

import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Admin Dashboard',
  description: 'Admin area with auth protection'
};

export default function RootLayout({
  children
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

input.content:
import { verifyAdmin } from '@/app/lib/auth';
import { forbidden } from 'next/navigation';

export default async function AdminPage() {
  const { isAdmin } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome to the protected admin area.</p>
    </main>
  );
}

import Link from 'next/link';

export default function Forbidden() {
  return (
    <main style={{ 
      display: 'flex', 
      flexDirection: 'column', 
      alignItems: 'center', 
      justifyContent: 'center', 
      height: '100vh',
      gap: '1rem'
    }}>
      <h1>403 - Forbidden</h1>
      <p>You do not have permission to access this page.</p>
      <Link href="/" style={{ textDecoration: 'underline', color: 'blue' }}>
        Return Home
      </Link>
    </main>
  );
}

